'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import Icon from '@/components/Icon';

interface Expense {
  id: string;
  cat: string;
  amount: number;
  note: string;
  date: string;
  ts: number;
}

interface AppState {
  budget: number;
  start: string;
  end: string;
  expenses: Expense[];
}

const KEY = 'estudyante-balanse.v1';

const CATS = [
  { id: 'food', label: 'Food', icon: 'utensils', color: '#FFB98F' },
  { id: 'transpo', label: 'Transpo', icon: 'bus', color: '#9FD8FF' },
  { id: 'school', label: 'School Supplies', icon: 'pencil-ruler', color: '#C9B8FF' },
  { id: 'load', label: 'Load & Data', icon: 'smartphone', color: '#A9ECC8' },
  { id: 'gala', label: 'Gala', icon: 'party-popper', color: '#FFA3CB' },
  { id: 'other', label: 'Others', icon: 'shapes', color: '#E8E4D8' },
];

const catById = (id: string) => CATS.find(c => c.id === id) || CATS[CATS.length - 1];

const pad = (n: number) => String(n).padStart(2, '0');
const iso = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const parse = (s: string) => {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, m - 1, d);
};
const addDays = (d: Date, n: number) => {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
};
const diffDays = (a: string, b: string) => Math.round((parse(b).getTime() - parse(a).getTime()) / 864e5);
const today = () => iso(new Date());
const monthRange = () => {
  const t = new Date();
  return [iso(new Date(t.getFullYear(), t.getMonth(), 1)), iso(new Date(t.getFullYear(), t.getMonth() + 1, 0))];
};
const weekRange = () => {
  const t = new Date();
  const s = addDays(t, -((t.getDay() + 6) % 7));
  return [iso(s), iso(addDays(s, 6))];
};
const shortDate = (s: string) => parse(s).toLocaleDateString('en-PH', { month: 'short', day: 'numeric' });
const peso = (v: number) => '₱' + Math.abs(v).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pesoR = (v: number) => '₱' + Math.round(Math.abs(v)).toLocaleString('en-PH');
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
const esc = (s: string) => String(s).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch] as string));

function sampleState(): AppState {
  const [start, end] = monthRange();
  const t = new Date();
  const d = (n: number) => {
    const x = iso(addDays(t, -n));
    return x < start ? start : x;
  };
  const raw: [number, string, number, string][] = [
    [0, 'food', 85, 'Siomai rice + gulaman'],
    [0, 'transpo', 26, 'Jeep papunta at pauwi'],
    [1, 'school', 150, 'Yellow pad + ballpen'],
    [1, 'load', 99, 'Data promo'],
    [1, 'food', 65, 'Fishball break'],
    [2, 'gala', 220, 'Milk tea with the tropa'],
    [2, 'transpo', 26, ''],
    [3, 'school', 45, 'Printing ng reviewer'],
    [4, 'food', 120, 'Tapsilog'],
    [5, 'other', 350, 'Ambag sa group project'],
    [6, 'transpo', 26, ''],
    [6, 'food', 95, 'Lunch sa karinderya'],
  ];
  const ts = Date.now();
  return {
    budget: 5000,
    start,
    end,
    expenses: raw.map(([n, cat, amount, note], i) => ({
      id: uid(),
      cat,
      amount,
      note,
      date: d(n),
      ts: ts - i * 1000,
    })),
  };
}

function loadState(): AppState | null {
  try {
    const s = JSON.parse(localStorage.getItem(KEY) || '');
    if (s && Array.isArray(s.expenses) && s.start && s.end) return s as AppState;
  } catch {}
  return null;
}

function dayLabel(s: string) {
  const d = diffDays(s, today());
  if (d === 0) return 'Today';
  if (d === 1) return 'Yesterday';
  return parse(s).toLocaleDateString('en-PH', { weekday: 'short', month: 'short', day: 'numeric' });
}

export default function Home() {
  const [mounted, setMounted] = useState(false);
  const [state, setState] = useState<AppState>({ budget: 0, start: '', end: '', expenses: [] });
  const [selectedCat, setSelectedCat] = useState('food');
  const [filter, setFilter] = useState('all');
  const [amount, setAmount] = useState('');
  const [dateIn, setDateIn] = useState('');
  const [note, setNote] = useState('');
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [toast, setToast] = useState<{ text: string; show: boolean }>({ text: '', show: false });
  const [newId, setNewId] = useState<string | null>(null);
  const [aiMsg, setAiMsg] = useState('Sinusuri ang gastos mo...');
  const [aiLoading, setAiLoading] = useState(false);
  const [displayedMsg, setDisplayedMsg] = useState('');
  const [loggerMode, setLoggerMode] = useState<'manual' | 'chat'>('manual');
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'assistant'; text: string }[]>([]);

  const [setBudget, setSetBudget] = useState('');
  const [setStart, setSetStart] = useState('');
  const [setEnd, setSetEnd] = useState('');
  const [setErr, setSetErr] = useState('');

  const amountRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const undoFn = useRef<(() => void) | null>(null);

  useEffect(() => {
    setMounted(true);

    const loaded = loadState();
    if (loaded) {
      setState(loaded);
    } else {
      const s = sampleState();
      setState(s);
      localStorage.setItem(KEY, JSON.stringify(s));
    }
    setDateIn(today());
  }, []);

  const save = useCallback((s: AppState) => {
    localStorage.setItem(KEY, JSON.stringify(s));
  }, []);

  const compute = useCallback(() => {
    const { budget, start, end, expenses } = state;
    const inPeriod = expenses.filter(e => e.date >= start && e.date <= end);
    const spent = inPeriod.reduce((s, e) => s + e.amount, 0);
    const remaining = budget - spent;
    const pct = budget > 0 ? (spent / budget) * 100 : 0;
    const total = diffDays(start, end) + 1;
    const t = today();
    const elapsed = Math.min(total, Math.max(0, diffDays(start, t) + 1));
    const left = Math.min(total, Math.max(0, diffDays(t, end) + 1));
    const timePct = (elapsed / total) * 100;
    const perDay = remaining > 0 && left > 0 ? remaining / left : 0;
    const byCat = CATS.map(c => ({ ...c, sum: inPeriod.filter(e => e.cat === c.id).reduce((s, e) => s + e.amount, 0) }))
      .filter(c => c.sum > 0)
      .sort((a, b) => b.sum - a.sum);

    let st: { color: string; chip: string; title: string; msg: string };
    if (pct > 100) st = { color: '#E5484D', chip: 'Lagpas na', title: 'Over budget ka na', msg: `Uy, lampas ka ng ${peso(-remaining)}. Tiis muna ha, darating din next allowance.` };
    else if (pct >= 85) st = { color: '#EA580C', chip: 'Ingat', title: 'Malapit na sa limit', msg: `${peso(remaining)} na lang yan for ${left} day${left === 1 ? '' : 's'}. Essentials muna, okay lang yan.` };
    else if (pct > timePct + 10 && left > 0) st = { color: '#D97706', chip: 'Medyo mabilis', title: 'Medyo mabilis ang gastos', msg: `Nagastos ka na ng ${Math.round(pct)}%, pero ${Math.round(timePct)}% lang ng panahon ang lumipas. Bawasan mo ha.` };
    else st = { color: '#16A34A', chip: 'Sakto pa', title: 'Chill ka pa', msg: left > 0 ? `Okay lang pace mo. Subukan mong bumaba sa ${pesoR(perDay)} per day para safe ka.` : 'Tapos na period, nakaabot ka within budget. Nice.' };

    return { inPeriod, spent, remaining, pct, total, elapsed, left, timePct, perDay, byCat, st };
  }, [state]);

  const showToast = useCallback((text: string, onUndo?: () => void) => {
    undoFn.current = onUndo || null;
    setToast({ text, show: true });
    clearTimeout(toastTimer.current ?? undefined);
    toastTimer.current = setTimeout(() => {
      setToast(t => ({ ...t, show: false }));
      undoFn.current = null;
    }, 5000);
  }, []);

  const handleSubmit = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    const amt = parseFloat(amount);
    if (!(amt > 0)) {
      amountRef.current?.classList.add('shake');
      setTimeout(() => amountRef.current?.classList.remove('shake'), 420);
      showToast('Enter an amount first.');
      return;
    }
    const exp: Expense = {
      id: uid(),
      amount: Math.round(amt * 100) / 100,
      cat: selectedCat,
      date: dateIn || today(),
      note: note.trim(),
      ts: Date.now(),
    };
    const newState = { ...state, expenses: [...state.expenses, exp] };
    setState(newState);
    save(newState);
    setNewId(exp.id);
    setTimeout(() => setNewId(null), 700);
    setAmount('');
    setNote('');
    showToast(`Logged ${peso(exp.amount)} for ${catById(exp.cat).label}`, () => {
      setState(prev => {
        const restored = { ...prev, expenses: prev.expenses.filter(x => x.id !== exp.id) };
        save(restored);
        return restored;
      });
    });
  }, [amount, selectedCat, dateIn, note, state, save, showToast]);

  const handleChatSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    const text = chatInput.trim();
    if (!text || chatLoading) return;

    setChatInput('');
    setChatMessages(prev => [...prev, { role: 'user', text }]);
    setChatLoading(true);

    try {
      const res = await fetch('/api/parse-expense', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: text }),
      });
      const data = await res.json();

      if (data.action === 'remove') {
        const last = [...state.expenses].sort((a, b) => b.ts - a.ts)[0];
        if (!last) {
          setChatMessages(prev => [...prev, { role: 'assistant', text: 'Wala pang naka-log na gastos.' }]);
          return;
        }
        const newState = { ...state, expenses: state.expenses.filter(x => x.id !== last.id) };
        setState(newState);
        save(newState);
        setChatMessages(prev => [
          ...prev,
          { role: 'assistant', text: `Binura ko na yung ₱${last.amount} ${catById(last.cat).label}.` },
        ]);
        return;
      }

      if (data.error) {
        setChatMessages(prev => [...prev, { role: 'assistant', text: 'Hindi ko naintindihan. Sabihin mo yung amount, halimbawa "siomai rice 85".' }]);
        return;
      }

      const exp: Expense = {
        id: uid(),
        amount: Number(data.amount),
        cat: data.category,
        date: today(),
        note: data.note || '',
        ts: Date.now(),
      };

      const newState = { ...state, expenses: [...state.expenses, exp] };
      setState(newState);
      save(newState);
      setNewId(exp.id);
      setTimeout(() => setNewId(null), 700);

      const spent = newState.expenses
        .filter(x => x.date >= newState.start && x.date <= newState.end)
        .reduce((s, x) => s + x.amount, 0);
      const remaining = newState.budget - spent;

      setChatMessages(prev => [
        ...prev,
        { role: 'assistant', text: `Logged ₱${exp.amount} ${catById(exp.cat).label}. Remaining ₱${remaining.toLocaleString('en-PH')}.` },
      ]);
    } catch {
      setChatMessages(prev => [...prev, { role: 'assistant', text: 'May error, try mo ulit.' }]);
    } finally {
      setChatLoading(false);
    }
  }, [chatInput, chatLoading, state, save]);

  const handleDelete = useCallback((id: string) => {
    const removed = state.expenses.find(x => x.id === id);
    if (!removed) return;
    setState(prev => {
      const next = { ...prev, expenses: prev.expenses.filter(x => x.id !== id) };
      save(next);
      return next;
    });
    showToast(`Deleted ${peso(removed.amount)} for ${catById(removed.cat).label}`, () => {
      setState(prev => {
        const restored = { ...prev, expenses: [...prev.expenses, removed] };
        save(restored);
        setNewId(removed.id);
        setTimeout(() => setNewId(null), 700);
        return restored;
      });
    });
  }, [state, save, showToast]);

  const handleSettingsSave = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    const budget = parseFloat(setBudget);
    if (!(budget > 0)) { setSetErr('Enter an allowance amount greater than ₱0.'); return; }
    if (!setStart || !setEnd) { setSetErr('Pick both a start and an end date.'); return; }
    if (setEnd < setStart) { setSetErr('The end date has to come after the start date.'); return; }
    const newState = { ...state, budget: Math.round(budget * 100) / 100, start: setStart, end: setEnd };
    setState(newState);
    save(newState);
    setSettingsOpen(false);
    showToast('Allowance settings saved');
  }, [setBudget, setStart, setEnd, state, save, showToast]);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key.toLowerCase() !== 'n' || e.metaKey || e.ctrlKey || e.altKey || settingsOpen) return;
      if (/^(input|textarea|select)$/i.test((document.activeElement as HTMLElement)?.tagName)) return;
      e.preventDefault();
      document.getElementById('logger')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      document.getElementById('amount')?.focus({ preventScroll: true });
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [settingsOpen]);

  // Fetch AI feedback on state change
  useEffect(() => {
    if (!mounted) return;
    const ctrl = new AbortController();
    setAiLoading(true);
    fetch('/api/feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ budget: state.budget, start: state.start, end: state.end, expenses: state.expenses, prev: aiMsg }),
      signal: ctrl.signal,
    })
      .then(r => r.json())
      .then(d => setAiMsg(d.msg))
      .catch(() => {})
      .finally(() => setAiLoading(false));
    return () => ctrl.abort();
  }, [mounted, state.budget, state.start, state.end, state.expenses]);

  // Auto-scroll chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [chatMessages, chatLoading]);

  // Typing effect
  useEffect(() => {
    if (aiLoading || !aiMsg) {
      setDisplayedMsg('');
      return;
    }
    let i = 0;
    setDisplayedMsg('');
    const interval = setInterval(() => {
      i++;
      setDisplayedMsg(aiMsg.slice(0, i));
      if (i >= aiMsg.length) clearInterval(interval);
    }, 20);
    return () => clearInterval(interval);
  }, [aiMsg, aiLoading]);

  if (!mounted) return null;

  const c = compute();
  const over = c.remaining < 0;
  const [remWhole, remCents] = Math.abs(c.remaining).toFixed(2).split('.');
  const counts: Record<string, number> = {};
  state.expenses.forEach(e => { counts[e.cat] = (counts[e.cat] || 0) + 1; });

  const list = state.expenses
    .filter(e => filter === 'all' || e.cat === filter)
    .sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : b.ts - a.ts));

  const groups: { date: string; items: Expense[] }[] = [];
  list.forEach(e => {
    const g = groups[groups.length - 1];
    if (g && g.date === e.date) g.items.push(e);
    else groups.push({ date: e.date, items: [e] });
  });

  const C = 2 * Math.PI * 76;

  return (
    <div style={{ '--status': c.st.color } as React.CSSProperties}>
      <div className="mx-auto max-w-6xl px-4 sm:px-6 pb-24">
        <header className="flex items-center justify-between gap-3 py-6 reveal">
          <div className="flex items-center gap-3 min-w-0">
            <div className="w-10 h-10 rounded-[14px] bg-[var(--lime)] text-[#0E0E10] grid place-items-center font-display font-extrabold text-xl -rotate-6">₱</div>
            <div className="min-w-0">
              <p className="font-display font-extrabold text-lg leading-none tracking-tight">Estudyante Balanse</p>
              <p className="text-xs text-muted mt-1">Budget mo, kontrolado mo.</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => { setSetBudget(String(state.budget)); setSetStart(state.start); setSetEnd(state.end); setSetErr(''); setSettingsOpen(true); }}
              className="pill hidden sm:inline-flex"
            >
              <Icon name="calendar" className="w-3.5 h-3.5 text-muted" />
              <span className="tnum">{shortDate(state.start)} – {shortDate(state.end)}</span>
            </button>
            <button
              onClick={() => { setSetBudget(String(state.budget)); setSetStart(state.start); setSetEnd(state.end); setSetErr(''); setSettingsOpen(true); }}
              className="icon-btn"
              aria-label="Allowance settings"
            >
              <Icon name="settings-2" />
            </button>
          </div>
        </header>

        <main className="grid grid-cols-1 gap-4 lg:grid-cols-12">
          {/* Hero */}
          <section
            className={`hero reveal lg:col-span-7 flex flex-col justify-between ${over ? 'is-over' : ''}`}
            style={{ '--d': '.05s' } as React.CSSProperties}
            aria-label="Balance summary"
          >
            <svg className="hero-art" viewBox="0 0 340 340" aria-hidden="true">
              <circle cx="170" cy="170" r="118" fill="var(--lime)" />
              <g className="orbit">
                <circle cx="170" cy="170" r="152" fill="none" stroke="rgba(255,255,255,.22)" strokeWidth="1.5" strokeDasharray="4 8" />
                <circle cx="18" cy="170" r="7" fill="var(--pink)" />
                <circle cx="300" cy="245" r="5" fill="#fff" />
              </g>
            </svg>
            <div className="coin hidden sm:grid" aria-hidden="true">₱</div>

            <div className="p-6 sm:p-8 sm:pr-40">
              <div className="flex items-center gap-3 flex-wrap">
                <span className="chip">
                  <span className="status-dot live" />
                  <span>{c.st.chip}</span>
                </span>
                <span className="eyebrow">{over ? 'Over budget by' : 'Remaining balance'}</span>
              </div>
              <h1 className="hero-num tnum mt-5" aria-live="polite">
                <span className="peso">₱</span>
                {Number(remWhole).toLocaleString('en-PH')}
                <span className="cents">.{remCents}</span>
              </h1>

              {/* Tats — real-time baon buddy feedback */}
              <div className="buddy mt-7">
                <span className="buddy-av"><Icon name="sparkles" /></span>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <p className="text-[13px] font-semibold">Tats</p>
                    <p className="eyebrow !text-[10px]">budget buddy · {aiLoading ? 'thinking' : 'online'}</p>
                  </div>
                  <p className="text-[14px] leading-snug mt-1 text-white/95">
                    {aiLoading && !displayedMsg ? (
                      <span className="inline-flex items-center gap-1 h-5">
                        <span className="w-1.5 h-1.5 rounded-full bg-white/70 animate-bounce" style={{ animationDelay: '0ms' }} />
                        <span className="w-1.5 h-1.5 rounded-full bg-white/70 animate-bounce" style={{ animationDelay: '150ms' }} />
                        <span className="w-1.5 h-1.5 rounded-full bg-white/70 animate-bounce" style={{ animationDelay: '300ms' }} />
                      </span>
                    ) : (
                      <>
                        {displayedMsg}
                        {displayedMsg.length < aiMsg.length && (
                          <span className="inline-block w-[2px] h-[14px] ml-0.5 align-middle animate-pulse bg-[var(--lime)]" />
                        )}
                      </>
                    )}
                  </p>
                </div>
              </div>
            </div>

            <div className="tiles">
              <button
                className="tile"
                onClick={() => { setSetBudget(String(state.budget)); setSetStart(state.start); setSetEnd(state.end); setSetErr(''); setSettingsOpen(true); }}
                aria-label="Edit total budget"
              >
                <span className="tile-label eyebrow">Budget <Icon name="pencil" /></span>
                <span className="tile-val tnum">{pesoR(state.budget)}</span>
                <span className="tile-sub">{shortDate(state.start)} – {shortDate(state.end)}</span>
              </button>
              <div className="tile" style={{ '--t': 'var(--lavender)' } as React.CSSProperties}>
                <span className="tile-label eyebrow">Spent</span>
                <span className="tile-val tnum">{pesoR(c.spent)}</span>
                <span className="tile-sub">{c.inPeriod.length} {c.inPeriod.length === 1 ? 'entry' : 'entries'}</span>
              </div>
              <div className="tile" style={{ '--t': 'var(--peach)' } as React.CSSProperties}>
                <span className="tile-label eyebrow">Safe / day</span>
                <span className="tile-val tnum">{pesoR(c.perDay)}</span>
                <span className="tile-sub">{c.left > 0 ? `${c.left} day${c.left === 1 ? '' : 's'} left` : 'Period ended'}</span>
              </div>
            </div>
          </section>

          {/* Budget meter */}
          <section
            className="glass reveal p-6 lg:col-span-5 flex flex-col"
            style={{ '--d': '.1s' } as React.CSSProperties}
            aria-label="Budget meter"
          >
            <div className="flex items-center justify-between">
              <h2 className="card-title flex items-center gap-3"><span className="title-ic bg-[var(--mint)]"><Icon name="gauge" /></span>Budget meter</h2>
              <span className="text-[13px] text-muted tnum">{pesoR(c.spent)} / {pesoR(state.budget)}</span>
            </div>

            <div className="flex items-center gap-5 sm:gap-6 mt-6">
              <div className="relative w-28 h-28 sm:w-32 sm:h-32 shrink-0">
                <svg viewBox="0 0 180 180" className="w-full h-full -rotate-90">
                  <circle cx="90" cy="90" r="76" className="ring-track" />
                  <circle
                    cx="90"
                    cy="90"
                    r="76"
                    className="ring-bar"
                    style={{
                      strokeDasharray: C,
                      strokeDashoffset: C * (1 - Math.min(c.pct, 100) / 100),
                      opacity: c.pct > 0 ? 1 : 0,
                    }}
                  />
                </svg>
                <div className="absolute inset-0 grid place-items-center text-center">
                  <div>
                    <p className="font-display font-extrabold text-4xl tracking-[-.05em] tnum leading-none">{Math.round(c.pct)}%</p>
                    <p className="eyebrow !text-[10px] mt-1.5">used</p>
                  </div>
                </div>
              </div>
              <div className="min-w-0">
                <p className="flex items-center gap-2">
                  <span className="status-dot" />
                  <span className="font-display font-bold text-xl tracking-tight leading-tight">{c.st.title}</span>
                </p>
                <p className="text-sm text-muted mt-2 leading-relaxed">{c.st.msg}</p>
              </div>
            </div>

            <div className="mt-6 space-y-3">
              <div>
                <div className="flex justify-between text-sm mb-1.5"><span className="text-muted">Time passed</span><span className="font-medium tnum">Day {c.elapsed} of {c.total}</span></div>
                <div className="bar"><i style={{ width: `${c.timePct}%`, background: 'var(--cobalt)' }} /></div>
              </div>
              <div>
                <div className="flex justify-between text-sm mb-1.5"><span className="text-muted">Money used</span><span className="font-medium tnum">{Math.round(c.pct)}%</span></div>
                <div className="bar"><i style={{ width: `${Math.min(100, c.pct)}%`, background: 'var(--status)' }} /></div>
              </div>
            </div>

            <div className="mt-auto pt-6">
              <p className="eyebrow mb-3">Where it&apos;s going</p>
              <div className="split">
                {c.byCat.length > 0
                  ? c.byCat.map(x => <i key={x.id} style={{ flexGrow: x.sum, background: x.color }} title={x.label} />)
                  : <i style={{ flexGrow: 1, background: 'var(--soft)' }} />}
              </div>
              <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-3 text-[13px]">
                {c.byCat.length > 0
                  ? c.byCat.map(x => (
                      <span key={x.id} className="inline-flex items-center gap-1.5">
                        <span className="w-2 h-2 rounded-full" style={{ background: x.color }} />
                        {x.label} <span className="text-muted tnum">{pesoR(x.sum)}</span>
                      </span>
                    ))
                  : <span className="text-muted">Nothing logged in this period yet.</span>}
              </div>
            </div>
          </section>

          {/* Logger */}
          <section
            id="logger"
            className="glass reveal p-6 lg:col-span-5 lg:col-start-8 lg:row-start-2 lg:sticky lg:top-6 self-start"
            style={{ '--d': '.15s' } as React.CSSProperties}
            aria-label="Log an expense"
          >
            <div className="flex items-center justify-between gap-3">
              <h2 className="card-title flex items-center gap-3"><span className="title-ic bg-[var(--lime)]"><Icon name="pen-line" /></span>Log gastos</h2>
              <span className="hidden sm:inline-flex items-center gap-1.5 text-xs text-muted">Press <span className="kbd">N</span></span>
            </div>
            <div className="mt-4">
              <div className="seg">
                <button
                  type="button"
                  className="pill sm"
                  aria-pressed={loggerMode === 'manual'}
                  onClick={() => setLoggerMode('manual')}
                >
                  Manual
                </button>
                <button
                  type="button"
                  className="pill sm"
                  aria-pressed={loggerMode === 'chat'}
                  onClick={() => setLoggerMode('chat')}
                >
                  <Icon name="sparkles" className="w-3.5 h-3.5" />
                  Chat
                </button>
              </div>
            </div>

            {loggerMode === 'chat' && (
              <div className="mt-4 flex flex-col" style={{ maxHeight: 420 }}>
                <div className="flex-1 overflow-y-auto no-scrollbar pr-1 -mr-1" style={{ minHeight: 140 }}>
                  {chatMessages.length === 0 && (
                    <div className="rounded-xl p-4 bg-[var(--soft)] border border-[var(--hair)]">
                      <p className="text-sm font-medium">Sabihin lang kung ano ginastos mo</p>
                      <p className="text-[13px] mt-1 leading-relaxed text-muted">
                        Halimbawa: &quot;kumain ako ng siomai rice 85&quot; o &quot;bayad jeep 26&quot;. Automatic ko icalculate.
                      </p>
                    </div>
                  )}
                  {chatMessages.map((m, i) => (
                    <div key={i} className={`mt-2 flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                      <div
                        className="max-w-[85%] rounded-2xl px-3.5 py-2 text-sm leading-snug"
                        style={
                          m.role === 'user'
                            ? { background: 'var(--cobalt)', color: '#fff', borderBottomRightRadius: 6 }
                            : { background: 'var(--soft)', color: 'rgb(var(--ink))', border: '1px solid var(--hair)', borderBottomLeftRadius: 6 }
                        }
                      >
                        {m.text}
                      </div>
                    </div>
                  ))}
                  {chatLoading && (
                    <div className="mt-2 flex justify-start">
                      <div className="rounded-2xl px-3.5 py-2.5 inline-flex items-center gap-1 bg-[var(--soft)] border border-[var(--hair)]">
                        <span className="w-1.5 h-1.5 rounded-full animate-bounce" style={{ background: 'rgb(var(--muted))', animationDelay: '0ms' }} />
                        <span className="w-1.5 h-1.5 rounded-full animate-bounce" style={{ background: 'rgb(var(--muted))', animationDelay: '150ms' }} />
                        <span className="w-1.5 h-1.5 rounded-full animate-bounce" style={{ background: 'rgb(var(--muted))', animationDelay: '300ms' }} />
                      </div>
                    </div>
                  )}
                  <div ref={chatEndRef} />
                </div>

                <form onSubmit={handleChatSubmit} className="mt-3" autoComplete="off">
                  <div className="flex items-center gap-2 rounded-2xl p-1.5 bg-[var(--soft)] border-[1.5px] border-transparent focus-within:border-[var(--cobalt)] focus-within:bg-white transition-colors">
                    <input
                      className="flex-1 bg-transparent outline-none text-sm px-2"
                      style={{ color: 'rgb(var(--ink))' }}
                      placeholder="Ano ginastos mo ngayon?"
                      value={chatInput}
                      onChange={e => setChatInput(e.target.value)}
                      disabled={chatLoading}
                    />
                    <button
                      type="submit"
                      className="w-9 h-9 rounded-xl grid place-items-center shrink-0 bg-[var(--cobalt)] text-white disabled:opacity-30 transition-opacity"
                      disabled={chatLoading || !chatInput.trim()}
                      aria-label="Send"
                    >
                      <Icon name="send" className="w-4 h-4" />
                    </button>
                  </div>
                </form>
              </div>
            )}

            {loggerMode === 'manual' && (
            <form onSubmit={handleSubmit} className="mt-4" noValidate autoComplete="off">
              <div ref={amountRef} className="amount-field" onClick={() => document.getElementById('amount')?.focus()}>
                <span className="peso">₱</span>
                <input
                  id="amount"
                  inputMode="decimal"
                  placeholder="0"
                  aria-label="Amount in pesos"
                  value={amount}
                  onChange={e => {
                    let v = e.target.value.replace(/[^\d.]/g, '');
                    const firstDot = v.indexOf('.');
                    if (firstDot !== -1) v = v.slice(0, firstDot + 1) + v.slice(firstDot + 1).replace(/\./g, '');
                    const [a, b] = v.split('.');
                    setAmount(b !== undefined ? a.slice(0, 7) + '.' + b.slice(0, 2) : a.slice(0, 7));
                  }}
                />
              </div>
              <div className="flex gap-2 mt-3 flex-wrap">
                {[20, 50, 100, 500].map(n => (
                  <button
                    key={n}
                    type="button"
                    className="pill sm plus"
                    onClick={() => setAmount(String(Math.round(((parseFloat(amount) || 0) + n) * 100) / 100))}
                  >
                    +{n}
                  </button>
                ))}
              </div>

              <p className="field-label mt-5">Category</p>
              <div className="grid grid-cols-3 gap-2" role="group" aria-label="Category">
                {CATS.map(cat => (
                  <button
                    key={cat.id}
                    type="button"
                    className="cat"
                    style={{ '--c': cat.color } as React.CSSProperties}
                    aria-pressed={selectedCat === cat.id}
                    onClick={() => setSelectedCat(cat.id)}
                  >
                    <span className="ic"><Icon name={cat.icon} /></span>
                    <span>{cat.label}</span>
                  </button>
                ))}
              </div>

              <div className="mt-5">
                <div className="field-label">
                  <label htmlFor="date">Date</label>
                  <span className="flex gap-1.5">
                    <button type="button" className="pill sm" onClick={() => setDateIn(today())}>Today</button>
                    <button type="button" className="pill sm" onClick={() => setDateIn(iso(addDays(new Date(), -1)))}>Yesterday</button>
                  </span>
                </div>
                <input id="date" type="date" className="input" value={dateIn} onChange={e => setDateIn(e.target.value)} />
              </div>

              <div className="mt-4">
                <label className="field-label" htmlFor="note"><span>Note</span><span className="opacity-70">Optional</span></label>
                <input id="note" className="input" maxLength={60} placeholder="Siomai rice sa canteen" value={note} onChange={e => setNote(e.target.value)} />
              </div>

              <button type="submit" className="submit mt-5">
                <span className="badge"><Icon name="plus" /></span>
                <span>Log expense</span>
              </button>
            </form>
            )}
          </section>

          {/* Feed */}
          <section
            className="glass reveal p-4 sm:p-6 lg:col-span-7 lg:col-start-1 lg:row-start-2 self-start"
            style={{ '--d': '.2s' } as React.CSSProperties}
            aria-label="Recent expenses"
          >
            <div className="px-2 sm:px-0">
              <h2 className="card-title flex items-center gap-3"><span className="title-ic bg-[var(--pink)]"><Icon name="receipt" /></span>Recent gastos</h2>
              <p className="text-sm text-muted mt-2">{c.inPeriod.length} {c.inPeriod.length === 1 ? 'entry' : 'entries'} this period, {peso(c.spent)} spent</p>
            </div>
            <div className="flex gap-2 overflow-x-auto no-scrollbar mt-4 px-2 sm:px-0" role="group" aria-label="Filter by category">
              {[{ id: 'all', label: 'All' }, ...CATS.filter(x => counts[x.id])].map(f => (
                <button
                  key={f.id}
                  type="button"
                  className="pill sm"
                  aria-pressed={filter === f.id}
                  onClick={() => setFilter(f.id)}
                >
                  {f.label}{f.id !== 'all' && counts[f.id] ? ` ${counts[f.id]}` : ''}
                </button>
              ))}
            </div>
            <div className="mt-2">
              {list.length === 0 ? (
                <div className="text-center py-14 px-4">
                  <div className="mx-auto w-14 h-14 rounded-2xl grid place-items-center bg-[var(--lime)] text-[#0E0E10] mb-4 rotate-6">
                    <Icon name="sparkles" />
                  </div>
                  <p className="font-display font-bold text-xl tracking-tight">Wala pang gastos dito</p>
                  <p className="text-sm text-muted mt-1">Log your first expense. It takes about three seconds.</p>
                </div>
              ) : (
                groups.map(g => (
                  <div key={g.date}>
                    <div className="day-head">
                      <span className="eyebrow">{dayLabel(g.date)}</span>
                      <span className="eyebrow tnum">{peso(g.items.reduce((s, e) => s + e.amount, 0))}</span>
                    </div>
                    {g.items.map(e => {
                      const cat = catById(e.cat);
                      const out = e.date < state.start || e.date > state.end;
                      return (
                        <div
                          key={e.id}
                          className={`row ${e.id === newId ? 'is-new' : ''} ${out ? 'out' : ''}`}
                          style={{ '--c': cat.color } as React.CSSProperties}
                        >
                          <div className="ic"><Icon name={cat.icon} /></div>
                          <div className="min-w-0 flex-1">
                            <p className="font-medium truncate">{esc(e.note || cat.label)}</p>
                            <p className="text-[13px] text-muted mt-0.5 truncate">{cat.label}{out ? ', outside this period' : ''}</p>
                          </div>
                          <p className="font-display font-bold text-lg tracking-tight tnum whitespace-nowrap">−{peso(e.amount)}</p>
                          <button
                            type="button"
                            className="del"
                            onClick={() => handleDelete(e.id)}
                            aria-label={`Delete ${e.note || cat.label}`}
                          >
                            <Icon name="trash-2" />
                          </button>
                        </div>
                      );
                    })}
                  </div>
                ))
              )}
            </div>
          </section>
        </main>

        <p className="text-center eyebrow mt-12">Prototype v0.1 · Your data stays in this browser</p>
      </div>

      {/* Toast */}
      <div className={`toast ${toast.show ? 'show' : ''}`} role="status" aria-live="polite">
        <span>{toast.text}</span>
        {undoFn.current && (
          <button
            type="button"
            onClick={() => {
              undoFn.current?.();
              undoFn.current = null;
              setToast(t => ({ ...t, show: false }));
            }}
          >
            Undo
          </button>
        )}
        <span className="tbar" />
      </div>

      {/* Settings dialog */}
      {settingsOpen && (
        <dialog open className="fixed inset-0 z-50" aria-label="Allowance settings">
          <form onSubmit={handleSettingsSave} className="sheet" noValidate>
            <div className="flex items-start justify-between gap-4">
              <div>
                <h3 className="card-title">Allowance settings</h3>
                <p className="text-sm text-muted mt-1">Set your budget and the dates it should last.</p>
              </div>
              <button type="button" className="icon-btn shrink-0" onClick={() => setSettingsOpen(false)} aria-label="Close">
                <Icon name="x" />
              </button>
            </div>

            <label className="block mt-5" htmlFor="setBudget"><span className="field-label">Allowance amount</span></label>
            <div className="amount-field sm">
              <span className="peso">₱</span>
              <input
                id="setBudget"
                inputMode="decimal"
                placeholder="5000"
                value={setBudget}
                onChange={e => { setSetBudget(e.target.value.replace(/[^\d.]/g, '').slice(0, 9)); }}
              />
            </div>

            <div className="flex gap-2 mt-4">
              <button type="button" className="pill sm" onClick={() => { const [s, e] = weekRange(); setSetStart(s); setSetEnd(e); }}>This week</button>
              <button type="button" className="pill sm" onClick={() => { const [s, e] = monthRange(); setSetStart(s); setSetEnd(e); }}>This month</button>
            </div>
            <div className="grid grid-cols-2 gap-2 mt-3">
              <label>
                <span className="field-label">Starts</span>
                <input type="date" className="input" value={setStart} onChange={e => setSetStart(e.target.value)} />
              </label>
              <label>
                <span className="field-label">Ends</span>
                <input type="date" className="input" value={setEnd} onChange={e => setSetEnd(e.target.value)} />
              </label>
            </div>
            {setErr && <p className="text-sm text-[var(--danger)] mt-3">{setErr}</p>}

            <button type="submit" className="submit mt-5">
              <span className="badge"><Icon name="check" /></span>
              Save changes
            </button>

            <div className="mt-6 pt-5 border-t border-[var(--hair)]">
              <p className="field-label">Your data</p>
              <div className="flex gap-2 flex-wrap">
                <button
                  type="button"
                  className="pill sm"
                  onClick={() => {
                    const s = sampleState();
                    setState(s);
                    save(s);
                    setSettingsOpen(false);
                    showToast('Sample data loaded');
                  }}
                >
                  Load sample data
                </button>
                <button
                  type="button"
                  className="pill sm danger"
                  onClick={() => {
                    if ((window as any).__armClear) {
                      setState(prev => {
                        const next = { ...prev, expenses: [] };
                        save(next);
                        return next;
                      });
                      setSettingsOpen(false);
                      showToast('Cleared all expenses');
                    } else {
                      (window as any).__armClear = true;
                      setTimeout(() => (window as any).__armClear = false, 3000);
                    }
                  }}
                >
                  Clear all expenses
                </button>
              </div>
            </div>
          </form>
        </dialog>
      )}
    </div>
  );
}
